export const STREET_CSS = "/* Generated by scripts/themes/sync-fanous-street.ts from Al-Ummah-Now/AlUmmahNow@a44fbed0fe2a8740fc74aadc58b024aadd6fdc94:packages/fanous-tokens/street/fanous-street.css. Do not edit. */\n/* Fanous lantern street: pre-made art behind the page, when \u003chtml> has the class fanous-street\n   (set by fanous-street.js when the active theme switches the street on).\n   - body::before: the soft distant lights (--fanous-street-lights), a small tile over the page;\n   - body::after: the street, a wide image tile of strings and lit lanterns across the full width.\n     It wraps both ways like a cylinder (left edge meets right, top meets bottom), so it repeats\n     with no joint at any width; it is centred on the page and shown at its CSS size by\n     image-set(… 2x), never stretched. A theme gives up to 4 variants (--fanous-street-tile-\u003cn>);\n     the server picks one per response (fanous-street.js pickStreetVariant) and sends it as\n     \u003chtml data-fanous-street-variant>, and only that one is fetched.\n   Both layers are as tall as the body and scroll with it: no fixed layers, no script, no\n   animation, no filters, nothing to repaint on scroll. Opaque cards simply cover the street; page\n   wrappers between the body and the cards stay transparent so it shows everywhere else.\n   Where its lanterns lie behind text an app sets --fanous-street-opacity to\n   var(--fanous-street-faint) (the theme's opacity at which every text colour keeps 4.5:1).\n   The body becomes its own stacking layer, so both paint above the body's background and below\n   every element. */\n\nhtml.fanous-street body {\n  position: relative;\n  isolation: isolate;\n}\n\nhtml.fanous-street body::before,\nhtml.fanous-street body::after {\n  content: '';\n  position: absolute;\n  inset: 0;\n  z-index: -1;\n  pointer-events: none;\n}\n\nhtml.fanous-street body::before {\n  background: var(--fanous-street-lights) 0 0 repeat;\n  opacity: var(--fanous-street-lights-opacity, 1);\n}\n\nhtml.fanous-street body::after {\n  background: var(--fanous-street-tile-pick, var(--fanous-street-tile)) 50% 0 repeat;\n  opacity: var(--fanous-street-opacity, 1);\n}\n\n/* The picked variant (a theme with fewer variants falls back to its first). Unused custom\n   properties fetch nothing, so only this tile downloads. */\nhtml[data-fanous-street-variant='2'] { --fanous-street-tile-pick: var(--fanous-street-tile-2, var(--fanous-street-tile)); }\nhtml[data-fanous-street-variant='3'] { --fanous-street-tile-pick: var(--fanous-street-tile-3, var(--fanous-street-tile)); }\nhtml[data-fanous-street-variant='4'] { --fanous-street-tile-pick: var(--fanous-street-tile-4, var(--fanous-street-tile)); }\n\n@media print {\n  html.fanous-street body::before,\n  html.fanous-street body::after { display: none; }\n}\n";
